package vn.edu.library.ui;

import vn.edu.library.data.Database;
import vn.edu.library.domain.UserSession;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;

public final class AssignmentsPanel extends JPanel {
    private final UserSession session;
    private final JTextField search=new JTextField(24);
    private final JLabel status=new JLabel(" ");
    private final DefaultTableModel model=new DefaultTableModel(){@Override public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(model);
    public AssignmentsPanel(UserSession session){this.session=session;setLayout(new BorderLayout(0,16));setBackground(UiStyle.CANVAS);setBorder(new EmptyBorder(27,30,24,30));add(header(),BorderLayout.NORTH);table.setRowHeight(33);table.setAutoCreateRowSorter(true);table.setFillsViewportHeight(true);JScrollPane sc=new JScrollPane(table);sc.setBorder(BorderFactory.createLineBorder(new Color(229,233,240)));add(sc,BorderLayout.CENTER);status.setForeground(UiStyle.MUTED);add(status,BorderLayout.SOUTH);load();}
    private JComponent header(){JPanel h=new JPanel(new BorderLayout(0,16));h.setOpaque(false);JPanel t=new JPanel();t.setOpaque(false);t.setLayout(new BoxLayout(t,BoxLayout.Y_AXIS));JLabel title=new JLabel("Phân công nhiệm vụ");title.setFont(title.getFont().deriveFont(Font.BOLD,25f));JLabel sub=new JLabel("Giao nhiệm vụ, thời hạn, mức độ ưu tiên và theo dõi tiến độ nhân viên.");sub.setForeground(UiStyle.MUTED);t.add(title);t.add(Box.createVerticalStrut(5));t.add(sub);h.add(t,BorderLayout.NORTH);search.putClientProperty("JTextField.placeholderText","Mã nhân viên, tên, nhiệm vụ");JButton find=new JButton("Tìm kiếm"),refresh=new JButton("Làm mới"),add=new JButton("Giao nhiệm vụ"),update=new JButton("Cập nhật tiến độ");add.setBackground(UiStyle.BLUE);add.setForeground(Color.WHITE);find.addActionListener(e->load());refresh.addActionListener(e->{search.setText("");load();});search.addActionListener(e->load());add.addActionListener(e->createAssignment());update.addActionListener(e->updateStatus());JPanel c=new JPanel(new FlowLayout(FlowLayout.LEFT,7,0));c.setOpaque(false);for(JComponent x:new JComponent[]{search,find,refresh,add,update})c.add(x);h.add(c,BorderLayout.SOUTH);return h;}
    private void load(){String term=search.getText().trim();String sql="SELECT a.assignment_id AS 'ID',s.staff_code AS 'Mã nhân viên',s.full_name AS 'Nhân viên',a.title AS 'Nhiệm vụ',a.details AS 'Nội dung',a.priority AS 'Ưu tiên',a.due_at AS 'Hạn hoàn thành',a.assignment_status AS 'Tiến độ',admin.full_name AS 'Người giao',a.assigned_at AS 'Ngày giao' FROM employee_assignments a JOIN staff_profiles s ON s.staff_id=a.staff_id JOIN staff_profiles admin ON admin.staff_id=a.assigned_by WHERE (?='' OR s.staff_code LIKE ? OR s.full_name LIKE ? OR a.title LIKE ?) ORDER BY a.assignment_status,a.due_at";try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement(sql)){String p="%"+term+"%";q.setString(1,term);for(int i=2;i<=4;i++)q.setString(i,p);try(ResultSet rs=q.executeQuery()){ResultSetMetaData md=rs.getMetaData();model.setRowCount(0);model.setColumnCount(0);for(int i=1;i<=md.getColumnCount();i++)model.addColumn(md.getColumnLabel(i));while(rs.next()){Object[] a=new Object[md.getColumnCount()];for(int i=1;i<=a.length;i++)a[i-1]=rs.getObject(i);model.addRow(a);}}status.setText("Đang hiển thị "+model.getRowCount()+" nhiệm vụ.");}catch(Exception ex){model.setRowCount(0);status.setText("Không tải được nhiệm vụ: "+ex.getMessage());}}
    private void createAssignment(){JTextField staffCode=new JTextField(22),title=new JTextField(22),due=new JTextField(java.time.LocalDate.now().plusDays(7).toString(),22);JTextArea details=new JTextArea(4,22);JComboBox<String> priority=new JComboBox<>(new String[]{"LOW","NORMAL","HIGH","URGENT"});JPanel p=new JPanel(new GridBagLayout());int y=0;y=row(p,y,"Mã nhân viên",staffCode);y=row(p,y,"Tên nhiệm vụ",title);y=row(p,y,"Nội dung",new JScrollPane(details));y=row(p,y,"Hạn (YYYY-MM-DD)",due);row(p,y,"Ưu tiên",priority);if(JOptionPane.showConfirmDialog(this,p,"Giao nhiệm vụ",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;if(staffCode.getText().isBlank()||title.getText().isBlank()){message("Mã nhân viên và tên nhiệm vụ là bắt buộc.",JOptionPane.WARNING_MESSAGE);return;}try{Date dueDate=Date.valueOf(due.getText().trim());try(Connection c=Database.getConnection()){long staff=0;try(PreparedStatement q=c.prepareStatement("SELECT staff_id FROM staff_profiles WHERE staff_code=? AND employment_status='ACTIVE'")){q.setString(1,staffCode.getText().trim());try(ResultSet r=q.executeQuery()){if(!r.next())throw new IllegalArgumentException("Nhân viên không tồn tại hoặc không còn làm việc.");staff=r.getLong(1);}}try(PreparedStatement q=c.prepareStatement("INSERT INTO employee_assignments(staff_id,title,details,priority,due_at,assigned_by) VALUES(?,?,?,?,?,?)")){q.setLong(1,staff);q.setString(2,title.getText().trim());q.setString(3,empty(details.getText()));q.setString(4,(String)priority.getSelectedItem());q.setDate(5,dueDate);q.setLong(6,staffId(c));q.executeUpdate();}load();message("Đã giao nhiệm vụ.",JOptionPane.INFORMATION_MESSAGE);}}catch(Exception ex){message("Không giao được nhiệm vụ: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private void updateStatus(){int view=table.getSelectedRow();if(view<0){message("Chọn một nhiệm vụ trước.",JOptionPane.INFORMATION_MESSAGE);return;}int row=table.convertRowIndexToModel(view);long id=Long.parseLong(model.getValueAt(row,0).toString());String current=model.getValueAt(row,7).toString();String[] options=switch(current){case "OPEN"->new String[]{"IN_PROGRESS","DONE","CANCELLED"};case "IN_PROGRESS"->new String[]{"DONE","CANCELLED"};default->new String[]{"OPEN","IN_PROGRESS","DONE","CANCELLED"};};String next=(String)JOptionPane.showInputDialog(this,"Trạng thái nhiệm vụ:","Cập nhật tiến độ",JOptionPane.PLAIN_MESSAGE,null,options,options[0]);if(next==null)return;try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement("UPDATE employee_assignments SET assignment_status=? WHERE assignment_id=?")){q.setString(1,next);q.setLong(2,id);q.executeUpdate();load();}catch(Exception ex){message("Không cập nhật được tiến độ: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private long staffId(Connection c)throws SQLException{try(PreparedStatement q=c.prepareStatement("SELECT staff_id FROM accounts WHERE account_id=? AND staff_id IS NOT NULL")){q.setLong(1,session.accountId());try(ResultSet r=q.executeQuery()){if(!r.next())throw new SQLException("Tài khoản chưa liên kết nhân viên.");return r.getLong(1);}}}
    private int row(JPanel p,int y,String label,JComponent input){GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(5,5,5,5);c.gridy=y;c.gridx=0;c.anchor=GridBagConstraints.WEST;p.add(new JLabel(label),c);c.gridx=1;c.fill=GridBagConstraints.HORIZONTAL;c.weightx=1;p.add(input,c);return y+1;}
    private String empty(String s){return s==null||s.trim().isEmpty()?null:s.trim();}
    private void message(String s,int t){JOptionPane.showMessageDialog(this,s,"Phân công nhiệm vụ",t);}
}
